<template>

<div class="zapatos">

    <div class="components">

        <FormularioZapatos
            ref="formulario"
            @actualizar-tabla="recargarTabla"
        />

        <TablaZapatos
            ref="tabla"
            @editar-zapato="editarZapato"
        />

    </div>

</div>

</template>

<script>

import FormularioZapatos from '@/components/FormularioZapatos.vue';
import TablaZapatos from '@/components/TablaZapatos.vue';

export default {

    name: "ZapatosView",

    components: {

        FormularioZapatos,
        TablaZapatos

    },

    methods: {

        recargarTabla() {

            this.$refs.tabla.listarZapatos();

        },

        editarZapato(z) {

            this.$refs.formulario.codigo = z.codigo;
            this.$refs.formulario.nombre = z.nombre;
            this.$refs.formulario.marca = z.marca;
            this.$refs.formulario.precio = z.precio;

        }

    }

}

</script>