<template>

<div class="container">
    <h1>Tabla Zapatos</h1>

    <table>
        <thead>
            <tr>
                <th>Código</th>
                <th>Nombre</th>
                <th>Marca</th>
                <th>Precio</th>
                <th>Acciones</th>
            </tr>
        </thead>

        <tbody>

            <tr v-for="z in zapatos" :key="z.codigo">

                <td>{{ z.codigo }}</td>
                <td>{{ z.nombre }}</td>
                <td>{{ z.marca }}</td>
                <td>{{ z.precio }}</td>

                <td>
                    <button @click="editar(z)">
                Editar
                     </button>

                    <button @click="eliminar(z.codigo)">
                        Eliminar
                    </button>
                </td>

            </tr>

        </tbody>

    </table>

</div>

</template>

<script>

import axios from "axios";

export default {

    name: "TablaZapatos",

    data() {
        return {
            zapatos: []
        }
    },

   methods: {

    listarZapatos() {

        axios.get("https://soothing-rejoicing-production-7ef0.up.railway.app/api/zapatos")

            .then((response) => {

                this.zapatos = response.data;

            })

            .catch((error) => {

                console.log(error);

            });

    },

    eliminar(codigo) {

        if (confirm("¿Desea eliminar este zapato?")) {

            axios.delete("https://soothing-rejoicing-production-7ef0.up.railway.app/api/zapatos" + codigo)

                .then(() => {

                    alert("Registro eliminado correctamente");

                    this.listarZapatos();

                })

                .catch((error) => {

                    console.log(error);

                    alert("Error al eliminar");

                });

        }

    },

    editar(z) {

        this.$emit("editar-zapato", z);

    }

},

    mounted() {

        this.listarZapatos();

    }

}

</script>

