<template>

<div class="container">

    <h1>Formulario Zapatos</h1>

    <form @submit.prevent="guardar">

        <div class="form-group">
            <label>Código</label>
            <input type="text" v-model="codigo" required>
        </div>

        <div class="form-group">
            <label>Nombre</label>
            <input type="text" v-model="nombre" required>
        </div>

        <div class="form-group">
            <label>Precio</label>
            <input type="number" v-model="precio" required>
        </div>

        <div class="form-group">
            <label>Marca</label>
            <input type="text" v-model="marca" required>
        </div>

        <button type="submit">Guardar</button>

        <button type="button" @click="consultar">
            Consultar
        </button>

        <button type="button" @click="actualizar">
            Actualizar
        </button>

        <button type="button" @click="limpiar">
            Limpiar
        </button>

    </form>

</div>

</template>

<script>

import axios from "axios";

const API_URL = "https://soothing-rejoicing-production-7ef0.up.railway.app/api/zapatos";

export default {

    data() {

        return {

            codigo: "",
            nombre: "",
            precio: "",
            marca: ""

        }

    },

    methods: {

        guardar() {

            axios.post(API_URL, {

                codigo: this.codigo,
                nombre: this.nombre,
                precio: this.precio,
                marca: this.marca

            })

            .then(() => {

            alert("Zapato guardado correctamente");

            this.$emit("actualizar-tabla");

            this.limpiar();

            })

            .catch((error) => {

                console.log(error);

                alert("Error al guardar");

            });

        },

        consultar() {

            axios.get(API_URL + "/" + this.codigo)

            .then((response) => {

                this.codigo = response.data.codigo;
                this.nombre = response.data.nombre;
                this.marca = response.data.marca;
                this.precio = response.data.precio;

                alert("Registro encontrado");

            })

            .catch((error) => {

                console.log(error);

                alert("No existe ese registro");

            });

        },

        actualizar() {

            axios.put(API_URL + "/actualizar/" + this.codigo, {

                codigo: this.codigo,
                nombre: this.nombre,
                marca: this.marca,
                precio: this.precio

            })

            .then(() => {

            alert("Registro actualizado");

            this.$emit("actualizar-tabla");

            this.limpiar();

            })

            .catch((error) => {

                console.log(error);

                alert("Error al actualizar");

            });

        },

        limpiar() {

            this.codigo = "";
            this.nombre = "";
            this.marca = "";
            this.precio = "";

        }

    }

}

</script>

